export async function reinstateMember(
  orgId: OrgId,
  userId: UserId,
  role: Role,
  invitedBy: UserId | null,
): Promise<Member> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(members)
    .set({
      role,
      status: "active",
      invitedBy,
      joinedAt: stamp,
      archivedAt: null,
      updatedAt: stamp,
    })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.userId, userId)))
    .returning()
    .get();

