/** Live member whose account email matches, ignoring letter case. */
export async function findLiveMemberByEmail(
  orgId: OrgId,
  email: string,
): Promise<Member | null> {
  const row = getDb()
    .select({ member: members })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        isNull(members.archivedAt),
        sql`lower(${users.email}) = ${email.trim().toLowerCase()}`,
      ),
    )
    .get();
  return row ? toMember(row.member) : null;
}

